SELECT 
FROM eqp_maintenance
WHERE is_deleted = 0

    AND (task_no LIKE CONCAT('%', #{keyword}, '%')
         OR operator LIKE CONCAT('%', #{keyword}, '%'))


    AND equipment_id = #{equipmentId}


    AND maintenance_type = #{maintenanceType}


    AND status = #{status}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM eqp_maintenance
WHERE is_deleted = 0

    AND (task_no LIKE CONCAT('%', #{keyword}, '%')
         OR operator LIKE CONCAT('%', #{keyword}, '%'))


    AND equipment_id = #{equipmentId}


    AND maintenance_type = #{maintenanceType}


    AND status = #{status}
